package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static ge.opensoft.openservice.WorkflowSupport.*;
import static org.junit.jupiter.api.Assertions.*;
import java.util.*;
final class TableReadAcceptance {
 static void configure(WorkflowSupport h,String table,List<String> roles) throws Exception {Map<String,Object> definition;try(var db=h.store.open()){definition=Service.schema(db,table);}definition.putIfAbsent("version",0);definition.put("record_roles",map("read",roles));var response=h.json("POST","/api/openservice/configuration?dry_run=false",ConfigurationAcceptance.bundle(table,definition),auth("admin"));assertEquals(200,response.statusCode(),html(response));}
 static void run(WorkflowSupport h) throws Exception {
  h.account("TableReader","reader");h.account("TableAgent","agent");h.account("TableRequester","requester");String table="u_table_read_"+id();var definition=ConfigurationAcceptance.definition();definition.put("label","Scoped confidential cases");definition.put("record_roles",map("read",List.of("admin","agent","reader","requester")));
  var install=h.json("POST","/api/openservice/configuration?dry_run=false",ConfigurationAcceptance.bundle(table,definition),auth("admin"));assertEquals(200,install.statusCode(),html(install));
  var created=h.json("POST","/api/now/table/"+table,map("short_description","Restricted source detail","amount","45"),auth("TableAgent"));assertEquals(201,created.statusCode());String record=object(parsed(created).get("result")).get("sys_id").toString(),report;
  try(var db=h.store.open()){String actor=PlatformFoundationTest.bind(db);var privateRecord=Service.create(db,table,map("short_description","Private extra","amount","90"),"admin");RecordAccess.change(db,privateRecord,actor,map("visibility","private","owner_id",actor));report=SavedReports.save(db,actor,map("name","Shared restricted report","table",table,"query",map("field","amount"),"shared",true)).get("report_id").toString();db.connection.commit();}
  assertEquals(201,h.json("POST","/api/openservice/comments/"+table+"/"+record,map("body","Confidential record comment"),auth("admin")).statusCode());
  var uploaded=h.request("POST","/api/now/attachment/file?table_name="+table+"&table_sys_id="+record+"&file_name=scope.txt","Confidential file bytes".getBytes(),"text/plain",auth("admin"));assertEquals(201,uploaded.statusCode());String attachment=object(parsed(uploaded).get("result")).get("sys_id").toString();
  assertEquals(200,h.get("/api/now/table/"+table+"/"+record,auth("TableReader")).statusCode());assertEquals(1,objects(parsed(h.get("/api/now/table/"+table,auth("TableReader"))).get("result")).size());
  configure(h,table,List.of("admin"));
  for(String user:List.of("TableReader","TableAgent","TableRequester")){
   for(String path:List.of("/api/now/table/"+table,"/api/now/table/"+table+"/"+record,"/api/now/stats/"+table+"?sysparm_count=true","/record/"+table+"/"+record,"/record/"+table+"/new","/workspace/"+table+"?search=Restricted","/export/"+table,"/api/openservice/analytics/"+table+"?field=amount","/analytics/"+table,"/reports/"+report+"/export.csv","/api/openservice/comments/"+table+"/"+record))assertEquals(403,h.get(path,auth(user)).statusCode(),user+" "+path);
   for(String path:List.of("/attachment/"+attachment,"/api/now/attachment/"+attachment,"/api/now/attachment/"+attachment+"/file"))assertEquals(404,h.get(path,auth(user)).statusCode());
   assertEquals(0,objects(parsed(h.get("/api/now/attachment?sysparm_query=table_sys_id="+record,auth(user))).get("result")).size());assertFalse(object(parsed(h.get("/api/openservice/schema",auth(user))).get("result")).containsKey(table));assertFalse(html(h.get("/dictionary",auth(user))).contains("Scoped confidential cases"));assertFalse(html(h.get("/audit",auth(user))).contains(record));
  }
  assertFalse(html(h.get("/",auth("TableReader"))).contains("Scoped confidential cases"));assertEquals(403,h.json("POST","/api/now/table/"+table,map("short_description","Cannot create blind"),auth("TableAgent")).statusCode());assertEquals(403,h.json("PATCH","/api/now/table/"+table+"/"+record,map("amount","55"),auth("TableAgent")).statusCode());
  String reader;try(var db=h.store.open()){reader=RecordAccess.owner(db,"TableReader");}var inspection=object(parsed(h.get("/api/openservice/users/"+reader+"/permissions?table="+table+"&record_id="+record,auth("admin"))).get("result"));assertEquals(false,object(inspection.get("read")).get("allowed"));
  configure(h,table,List.of("admin","reader"));assertEquals(1,objects(parsed(h.get("/api/now/table/"+table,auth("TableReader"))).get("result")).size());assertTrue(html(h.get("/reports/"+report+"/export.csv",auth("TableReader"))).contains("45"));assertFalse(html(h.get("/reports/"+report+"/export.csv",auth("TableReader"))).contains("135"));assertEquals(200,h.json("PATCH","/api/openservice/users/"+reader+"/role",map("role","agent"),auth("admin")).statusCode());assertEquals(403,h.get("/api/now/table/"+table,auth("TableReader")).statusCode());assertEquals(200,h.json("PATCH","/api/openservice/users/"+reader+"/role",map("role","reader"),auth("admin")).statusCode());
  for(Object roles:List.of(List.of("reader"),List.of("admin","unknown"),"admin")){Map<String,Object> invalid;try(var db=h.store.open()){invalid=Service.schema(db,table);}invalid.put("record_roles",map("read",roles));assertEquals(400,h.json("POST","/api/openservice/configuration",ConfigurationAcceptance.bundle(table,invalid),auth("admin")).statusCode());}
  // Table access never grants a restricted field, and published articles use a separate deliberate grant.
  Map<String,Object> fieldSchema;try(var db=h.store.open()){fieldSchema=Service.schema(db,table);}object(object(fieldSchema.get("field_rules")).get("amount")).put("read_roles",List.of("admin"));assertEquals(200,h.json("POST","/api/openservice/configuration?dry_run=false",ConfigurationAcceptance.bundle(table,fieldSchema),auth("admin")).statusCode());
  assertFalse(object(object(parsed(h.get("/api/openservice/schema",auth("TableReader"))).get("result")).get(table)).toString().contains("amount"));assertFalse(object(parsed(h.get("/api/now/table/"+table+"/"+record,auth("TableReader"))).get("result")).containsKey("amount"));assertEquals(400,h.get("/reports/"+report+"/export.csv",auth("TableReader")).statusCode());
  Map<String,Object> originalKnowledge;String article;try(var db=h.store.open()){String actor=PlatformFoundationTest.bind(db);originalKnowledge=Service.schema(db,"kb_knowledge");article=KnowledgeSearchAcceptance.article(db,actor,"Published table policy answer","Intentionally shared with the workspace");db.connection.commit();}
  configure(h,"kb_knowledge",List.of("admin"));try{assertEquals(403,h.get("/api/now/table/kb_knowledge/"+article,auth("TableReader")).statusCode());assertEquals(200,h.get("/api/openservice/knowledge/"+article,auth("TableReader")).statusCode());}finally{ReferencePickerAcceptance.writeSchema(h,"kb_knowledge",originalKnowledge);}
  // Deleted records lack retained table classification; only administrators can inspect that history.
  Map<String,Object> event;try(var db=h.store.open()){event=db.one("SELECT * FROM os_event WHERE record_id=? AND action='created'",record);}
  assertEquals(204,h.json("DELETE","/api/now/table/"+table+"/"+record,map(),auth("admin")).statusCode());
  try(var db=h.store.open()){db.viewerId=reader;db.viewerRole="reader";assertEquals(map(),FieldAccess.event(db,event).get("detail"));}
assertFalse(html(h.get("/audit",auth("TableReader"))).contains("Confidential record comment"));assertTrue(html(h.get("/audit",auth("admin"))).contains("Confidential record comment"));
  new Store(h.environment);assertEquals(200,h.get("/api/now/table/"+table,auth("TableReader")).statusCode());
  try(var db=h.store.open()){for(var row:db.all("SELECT name,definition FROM os_schema")){var schema=object(row.get("definition"));schema.put("record_roles",map("read",List.of("admin")));db.update("UPDATE os_schema SET definition="+db.jsonParameter()+" WHERE name=?",JSON.writeValueAsString(schema),row.get("name"));}db.viewerId=reader;db.viewerRole="reader";var values=new ArrayList<Object>();assertEquals(0,db.count("SELECT COUNT(*) FROM os_record WHERE "+RecordAccess.filter(db,"os_record.sys_id",values),values.toArray()));db.connection.rollback();}
 }
}
